func TestJSONMarshalingAccount(t *testing.T) {
	t.Run("MarshalUnmarshal", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &Account{}

		// Act - Marshal to JSON
		data, err := json.Marshal(obj)
		require.NoError(t, err, "marshaling should succeed")
		assert.NotNil(t, data, "marshaled data should not be nil")
		assert.NotEmpty(t, data, "marshaled data should not be empty")

		// Unmarshal back and verify round-trip
		var unmarshaled Account
		err = json.Unmarshal(data, &unmarshaled)
		assert.NoError(t, err, "round-trip unmarshal should succeed")
	})

	t.Run("UnmarshalInvalidJSON", func(t *testing.T) {
		t.Parallel()
		var obj Account
		err := json.Unmarshal([]byte(`{invalid json}`), &obj)
		assert.Error(t, err, "unmarshaling invalid JSON should return an error")
	})

	t.Run("UnmarshalEmptyObject", func(t *testing.T) {
		t.Parallel()
		var obj Account
		err := json.Unmarshal([]byte(`{}`), &obj)
		assert.NoError(t, err, "unmarshaling empty object should succeed")
	})
}

func TestRequiredNullableRoundTripAccount(t *testing.T) {
	requiredNullableKeys := []string{
		"phone",
		"address",
	}
	marshalToMap := func(t *testing.T, obj *Account) map[string]json.RawMessage {
		data, err := json.Marshal(obj)
		require.NoError(t, err, "marshaling should succeed")
		var result map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(data, &result), "marshaled data should be a JSON object")
		return result
	}

	t.Run("NullPreserved", func(t *testing.T) {
		t.Parallel()
		var obj Account
		require.NoError(t, json.Unmarshal([]byte(`{"phone":null,"address":null}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range requiredNullableKeys {
			value, ok := result[key]
			require.True(t, ok, "required nullable field %q received as null should be present in the output", key)
			assert.Equal(t, "null", string(value), "required nullable field %q received as null should be null in the output", key)
		}
	})

	t.Run("AbsentStaysAbsent", func(t *testing.T) {
		t.Parallel()
		var obj Account
		require.NoError(t, json.Unmarshal([]byte(`{}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range requiredNullableKeys {
			assert.NotContains(t, result, key, "required nullable field %q absent from the input should be absent from the output", key)
		}
	})

	t.Run("FreshValueOmits", func(t *testing.T) {
		t.Parallel()
		result := marshalToMap(t, &Account{})
		for _, key := range requiredNullableKeys {
			assert.NotContains(t, result, key, "required nullable field %q should be omitted from a freshly constructed value", key)
		}
	})
}

